// The receipt these tests render is the SERVER's, not one written here.
//
// `packages/api-core/tests/fixtures/objects/v<version>/specs/receipt.json` is
// generated by `packages/api-core/tests/fixtures/objects/generate.py` — a dump
// of `alkera_core.schemas.objects.Receipt` as today's writer emits it. Reading
// it means a field the writer renames cannot stay green here: the browser's
// receipt panel asserted against its OWN spelling for as long as it existed,
// and rendered "Connection —" on the one surface whose job is to be checkable.
//
// The version directory is discovered rather than pinned, so a schema bump does
// not silently leave this reading a stale receipt.

import { readdirSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "../../../../../../..");
const FIXTURES = resolve(REPO_ROOT, "packages/api-core/tests/fixtures/objects");

function newestVersionDir(): string {
  const versions = readdirSync(FIXTURES)
    .filter((name) => /^v\d+_\d+_\d+$/.test(name))
    .sort((a, b) => {
      const parts = (name: string) => name.slice(1).split("_").map(Number);
      const [al, am, ap] = parts(a);
      const [bl, bm, bp] = parts(b);
      return al - bl || am - bm || ap - bp;
    });
  if (versions.length === 0) throw new Error(`no object spec fixtures under ${FIXTURES}`);
  return versions[versions.length - 1];
}

export const SERVER_RECEIPT = JSON.parse(
  readFileSync(join(FIXTURES, newestVersionDir(), "specs", "receipt.json"), "utf-8"),
) as Record<string, string | number | Record<string, unknown> | null>;

/** The receipt a real promote + upload actually LEAVES on the object.
 *
 *  `generate.py`'s dump above is what today's writer emits for the model — its
 *  `principal_chain` is a hand-authored `{acting, chain}`. The routes write
 *  something else: `promoted_by` at the promote and `uploaded_by` at the upload,
 *  each a nested actor-chain record the server resolves, with the daemon's own
 *  `principal` alongside. This file is that receipt, recorded from the real
 *  routes by `apps/backend/tests/test_daemon_rest_seam.py` (with
 *  `SEAM_FIXTURE_WRITE=1`), so the panel is also rendered over the bytes a
 *  reader will really open. */
export const RECEIPT_FROM_ROUTES = JSON.parse(
  readFileSync(join(FIXTURES, "seam", "receipt_from_routes.json"), "utf-8"),
) as Record<string, string | number | Record<string, unknown> | null>;
